from confluent_kafka import Consumer, KafkaException

consumer = Consumer({
    "bootstrap.servers": "localhost:9092",
    "group.id": "analytics",            # a different group.id gets its own copy
    "auto.offset.reset": "earliest",    # replay from the start if no offset yet
    "enable.auto.commit": True,          # commit offsets (the bookmark) periodically
})

consumer.subscribe(["orders"])

try:
    while True:
        msg = consumer.poll(timeout=1.0)   # PULL model: we ask for records
        if msg is None:
            continue                       # no data right now; loop again
        if msg.error():
            raise KafkaException(msg.error())
        print(f"partition={msg.partition()} offset={msg.offset()} value={msg.value().decode()}")
except KeyboardInterrupt:
    pass
finally:
    consumer.close()                       # commits final offsets and leaves the group
